SELECT n.gender, rt.role, cn.name, COUNT(*)
FROM title as t, movie_companies as mc, company_name as cn, company_type as ct, kind_type as kt, cast_info as ci, name as n, role_type as rt, movie_info as mi1, info_type as it1, person_info as pi, info_type as it2, non_leaf_398
WHERE it2.id = pi.info_type_id AND ci.role_id = rt.id AND mc.movie_id = t.id AND non_leaf_398.mi1_movie_id = t.id AND ci.person_id = n.id AND n.id = pi.person_id AND (t.production_year <= 2015) AND ci.movie_id = t.id AND (pi.info ILIKE '%of%') AND (rt.role IN ('actress','cinematographer','guest','miscellaneous crew','writer')) AND ci.movie_id = non_leaf_398.mi1_movie_id AND kt.id = t.kind_id AND ct.id = mc.company_type_id AND ci.movie_id = mc.movie_id AND ci.person_id = pi.person_id AND (mi1.info ILIKE '%br%') AND it1.id = non_leaf_398.mi1_info_type_id AND cn.id = mc.company_id AND (kt.kind IN ('episode','movie','tv mini series','tv series','video game')) AND (t.production_year >= 1990) AND (it1.id IN ('5')) AND (it2.id IN ('38'));